INSERT INTO academy_courses (slug, title, description, icon, color, order_index, difficulty, requires_pro, is_published) VALUES
  ('macro-mechanics', 'Macro Mechanics: Rates, Yields & Sector Rotation', 'Rates don''t just make loans pricier, they change what future profits are worth today. Learn the discount-rate effect on growth vs. value, how to read the yield curve and credit spreads as market-based risk gauges, oil''s two-sided impact, and how money rotates across sectors as the macro regime shifts.', 'Radar', 'indigo', 13, 'advanced', TRUE, TRUE)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO academy_lessons (course_id, slug, title, type, order_index, xp_reward, content)
SELECT
  (SELECT id FROM academy_courses WHERE slug = 'macro-mechanics'),
  v.slug, v.title, v.type, v.order_index, v.xp_reward, v.content
FROM (VALUES
  ('discount-rate-growth-vs-value', 'Why Rate Hikes Hit Growth Stocks Harder', 'read', 0, 10, '{"sections":[{"text":"A stock''s price isn''t just about how much a company earns this year. It reflects the market''s best guess at ALL the profits that company will ever make, added up and pulled back to what they''re worth to you today. That last part matters: a dollar you''ll only get many years from now is worth less to you right now than a dollar you already have.","highlightedTerms":[{"term":"Discount Rate","definition":"The rate used to translate a company''s future profits into what they''re worth today. When interest rates rise, this rate rises too, shrinking the value of profits expected far in the future, which is why growth stocks tend to fall harder than value stocks when rates climb."}]},{"text":"Here''s the intuition. If someone promises you a dollar in 10 years, that''s less exciting than a dollar today that you could put to work earning a return. Interest rates set how much that ''work'' pays. When the Federal Reserve raises interest rates, the reward for having money today goes up, so a far-off dollar looks even less appealing by comparison. That widening gap is exactly what a rising discount rate does.","highlightedTerms":[{"term":"Federal Reserve","definition":"The United States central bank. It sets interest rate policy to try to keep inflation in check and the economy growing at a healthy pace."},{"term":"Interest Rate","definition":"What it costs to borrow money, set in large part by the Fed''s policy rate. When rates rise, loans, mortgages, and business borrowing all get more expensive."}]},{"text":"Rising rates shrink the value of profits expected far in the future much more than profits arriving soon. That''s why the type of stock matters. A Growth Stock is priced mainly on big profits expected years down the road, so it gets hit hardest. A Value Stock leans on cash the company already generates today, so it''s less exposed.","highlightedTerms":[{"term":"Growth Stock","definition":"A stock priced mainly on profits expected years from now, not today''s earnings. Its value leans heavily on future cash flow, making it more sensitive to rising interest rates."},{"term":"Value Stock","definition":"A stock priced mainly on the cash it already generates today, not a distant growth story. Its value leans less on future cash flow, making it comparatively steadier when interest rates rise."}]},{"text":"There''s a second punch, too. Many fast-growing companies borrow heavily to fund their expansion. When rates rise, their borrowing costs climb, eating into profits at the same time their future earnings are being discounted harder. Two headwinds hitting at once make the sting worse.","highlightedTerms":[{"term":"Long-Term Debt","definition":"Debt that doesn''t come due for more than a year. High long-term debt can be risky if interest rates rise or the business slows."}]}],"funFact":"During the Federal Reserve''s rapid rate-hiking cycle in 2022, growth stocks broadly fell much harder than value stocks as rates climbed sharply. Think of it as a rough real-world illustration of the idea, not a precise statistic: the exact gap varied depending on how you measured it."}'::jsonb),
  ('yield-curve-and-credit-spreads', 'Reading the Yield Curve & Credit Spreads', 'read', 1, 10, '{"sections":[{"text":"The Yield Curve is a simple line that plots how much US government bonds pay you back, sorted from short-term loans to long-term loans. Normally, the line slopes up: if you lend the government money for 10 years, you expect more reward than lending for just a few months, because you are tying up your cash longer. When yields on short-term bonds climb above long-term ones, that flips the line upside down. This is called Yield Curve Inversion.","highlightedTerms":[{"term":"Yield Curve","definition":"A line plotting Treasury bond yields from short-term to long-term. Normally, longer-term yields are higher. When that flips, it''s called an inversion."},{"term":"Yield Curve Inversion","definition":"When short-term Treasury yields rise above long-term yields. It has historically been one of the more reliable warning signs of a coming recession."}]},{"text":"Why would short-term yields ever pay more than long-term ones? It usually means investors expect the Federal Reserve to cut interest rates later on, often because they see economic weakness coming. An inversion has been one of the more closely watched warning signs of a possible Recession, though it is a signal to watch, not a promise of what will happen.","highlightedTerms":[{"term":"Federal Reserve","definition":"The United States central bank. It sets interest rate policy to try to keep inflation in check and the economy growing at a healthy pace."},{"term":"Recession","definition":"A significant, widespread decline in economic activity lasting more than a few months, typically marked by falling output, employment, and spending."}]},{"text":"A Credit Spread is the extra yield investors demand to hold riskier company bonds instead of super-safe government debt. When people get nervous, that gap widens because they want more reward for taking on risk. BullPen''s Market Mood tool already tracks a live version of this idea: it watches demand for junk bonds versus safer bonds, so you can check a real credit-spread-like signal yourself.","highlightedTerms":[{"term":"Credit Spread","definition":"The extra yield investors demand to hold riskier corporate bonds over safe government debt. Widening spreads signal investors are pricing in more risk of default."}]},{"text":"Here is what ties these two together: both the yield curve and credit spreads are set by real money at stake, not opinions or headlines. When millions of investors are actually buying and selling bonds, their combined bets reveal what they truly expect. That is why professionals treat both as leading indicators, early clues worth watching before the news catches up.","highlightedTerms":[{"term":"Interest Rate","definition":"What it costs to borrow money, set in large part by the Fed''s policy rate. When rates rise, loans, mortgages, and business borrowing all get more expensive."}]}],"funFact":"Inverted yield curves have shown up before most US recessions in recent decades, which is why they get so much attention. But they have also flashed a few false alarms, so seasoned investors treat an inversion as a caution flag rather than a crystal ball."}'::jsonb),
  ('oil-and-sector-rotation', 'Oil''s Two-Sided Effect and How Sectors Rotate', 'read', 2, 10, '{"sections":[{"text":"When the price of oil goes up, it affects the whole economy in one big way. Fuel and raw materials cost more, which pushes up the prices of many goods, and that feeds inflation. When inflation rises, there is often upward pressure on interest rates, the cost of borrowing money.","highlightedTerms":[{"term":"Oil Price","definition":"The market price of crude oil. It ripples into transportation and manufacturing costs, consumer prices, and energy company profits, sometimes pulling the market in two different directions at once."},{"term":"Inflation","definition":"The rate at which prices for goods and services increase over time. High inflation erodes what your money can buy and often pushes the Fed to raise interest rates."},{"term":"Interest Rate","definition":"What it costs to borrow money, set in large part by the Fed''s policy rate. When rates rise, loans, mortgages, and business borrowing all get more expensive."}]},{"text":"But oil has a second, more targeted effect that points in the opposite direction for different companies. Energy producers often earn bigger profits when oil is expensive, because they sell it for more. Meanwhile, airlines, shippers, and other fuel-heavy businesses get squeezed, since the same high oil price is now a bigger bill for them. One macro signal can be good news for one part of the market and bad news for another at the very same time.","highlightedTerms":[{"term":"Profit Margin","definition":"What percentage of revenue the company keeps as profit after all costs. A 20% margin means the company keeps $0.20 for every $1.00 it earns."}]},{"text":"This helps explain Sector Rotation, the way money systematically moves between groups of stocks as the economic backdrop shifts. When rates rise and inflation runs hot, investors often rotate out of pricey growth and technology stocks and into energy, financials, and other value-oriented sectors. When rates fall and growth is favored again, the rotation tends to reverse.","highlightedTerms":[{"term":"Sector Rotation","definition":"When investors shift money out of some sectors and into others as economic conditions change, for example moving from growth-heavy tech into steadier value sectors as rates rise."},{"term":"Growth Stock","definition":"A stock priced mainly on profits expected years from now, not today''s earnings. Its value leans heavily on future cash flow, making it more sensitive to rising interest rates."},{"term":"Value Stock","definition":"A stock priced mainly on the cash it already generates today, not a distant growth story. Its value leans less on future cash flow, making it comparatively steadier when interest rates rise."}]},{"text":"Tie this together with what you have already learned. No single macro signal, whether interest rates, the yield curve, credit spreads, or oil, works in isolation. Professional investors read them together to judge the overall macro regime and figure out which sectors that environment tends to reward.","highlightedTerms":[{"term":"Yield Curve","definition":"A line plotting Treasury bond yields from short-term to long-term. Normally, longer-term yields are higher. When that flips, it''s called an inversion."},{"term":"Credit Spread","definition":"The extra yield investors demand to hold riskier corporate bonds over safe government debt. Widening spreads signal investors are pricing in more risk of default."}]}],"funFact":"When oil prices spike, energy stocks and airline stocks can move in exactly opposite directions on the very same day, driven by the very same headline."}'::jsonb),
  ('macro-mechanics-quiz', 'Quick Check: Macro Mechanics', 'quiz', 3, 20, '{"questions":[{"question":"The Federal Reserve raises interest rates. You hold two stocks: a fast-growing software company that isn''t profitable yet (its value rests on big profits expected 10+ years from now) and a mature, profitable consumer staples company (think toothpaste and soap). Which stock is likely to fall harder?","options":["The consumer staples company, because people stop buying everyday goods","The software company, because its value leans on distant future profits that are now discounted more heavily","They fall by exactly the same amount","Neither is affected by rate changes"],"correctIndex":1,"explanation":"When rates rise, profits expected far in the future are worth less today (they get ''discounted'' more), so a company priced mainly on distant earnings takes a bigger hit than one earning steady profits right now."},{"question":"You notice that a 2-year Treasury bond is paying a higher yield than a 10-year Treasury bond, meaning short-term yields have risen above long-term yields. This is called a ''yield curve inversion.'' What has this historically tended to signal?","options":["That the economy will boom for years","That investors expect the Fed to cut rates later due to economic weakness, a fairly reliable recession warning sign","That short-term bonds are always the better buy","Nothing meaningful, it''s just random noise"],"correctIndex":1,"explanation":"Long-term yields dropping below short-term ones suggests investors expect the Fed to cut rates down the road because they see trouble ahead, which is why inversions have preceded many past recessions."},{"question":"A supply shock pushes oil prices up about 25 percent. You own two stocks: an airline (which burns huge amounts of fuel) and an oil producer (which pumps and sells oil). What''s the most likely outcome?","options":["Both stocks rise together because oil is up","Both stocks fall together","The oil producer likely benefits from higher prices while the airline gets squeezed by higher fuel costs","The airline benefits and the oil producer suffers"],"correctIndex":2,"explanation":"The same price move helps a seller of oil and hurts a heavy buyer of oil, showing that one macro event can push different parts of the market in opposite directions."}]}'::jsonb),
  ('macro-mechanics-match', 'Match the Market Gauges', 'match', 4, 15, '{"pairs":[{"term":"Discount Rate","definition":"The rate used to shrink future money into what it''s worth today."},{"term":"Growth Stock","definition":"A company expected to grow fast, so investors pay up for it."},{"term":"Value Stock","definition":"A company priced cheaply compared to what it actually earns."},{"term":"Yield Curve","definition":"A line showing interest rates for bonds of different lengths."},{"term":"Yield Curve Inversion","definition":"When short-term bonds pay more than long-term ones, often a warning sign."},{"term":"Credit Spread","definition":"The extra interest risky borrowers pay over safe ones."},{"term":"Sector Rotation","definition":"Moving money between industries as the economy shifts."}]}'::jsonb),
  ('rate-hike-portfolio-call', 'The Rate Hike Rotation', 'scenario', 5, 25, '{"setup":"The Federal Reserve just raised interest rates for the third time this year, and it was a bigger jump than most people expected. At the same time, the 10-year Treasury yield (basically the interest rate the government pays to borrow for 10 years) climbed too. My portfolio is stuffed with high-growth tech companies that aren''t profitable yet but have soared over the past two years. A friend says I should shift some of that money into energy and financial stocks instead. What should I do?","choices":[{"label":"Nothing. Interest rates are a bank thing, they don''t really move stock prices.","feedback":"It feels separate, but rates and stock prices are actually deeply connected. Here''s the idea: a growth stock''s value is mostly built on profits it hopes to earn many years from now. When rates rise, those far-off future dollars are worth less in today''s terms (money you get later is worth less when you could earn more interest just by waiting). That''s called the discount-rate effect, and it hits not-yet-profitable growth stocks the hardest. So this misses a very real mechanism.","isCorrect":false},{"label":"Trim some growth exposure and rebalance a portion toward sectors that tend to hold up better when rates and inflation are rising, while keeping meaningful growth positions.","feedback":"Nicely balanced. Rising rates shrink the present-day value of profits that are far in the future, and that''s exactly what your growth stocks are priced on, so they tend to feel the most pain. Sectors like energy and financials often hold up better in this kind of environment. But the smart move is calibrated rebalancing (adjusting your mix in measured steps), not a total escape. You reduce your vulnerability without betting the whole farm on being right about the future.","isCorrect":true},{"label":"Sell 100 percent of my growth stocks right now and put everything into energy.","feedback":"I understand the urge to act boldly, but this just swaps one concentrated bet for another. You''d be trading heavy exposure to one sector for heavy exposure to a different sector, so if energy stumbles you''re right back in a risky spot. The whole point of sector rotation is thoughtful, partial rebalancing to spread out risk, not an all-or-nothing gamble. Big all-in moves also often happen right after the news is already priced in.","isCorrect":false}]}'::jsonb)
) AS v(slug, title, type, order_index, xp_reward, content)
ON CONFLICT (course_id, slug) DO NOTHING;
